// One item per Merge input, in input order: profile, tech stack, news, funding, then the sheet row.
const [enrich, tech, news, funding, row] = $input.all().map((i) => i.json);
const org = (enrich.output && enrich.output.organization) || {};

const techNames = [];
try {
  for (const path of tech.output.Results[0].Result.Paths) {
    for (const t of path.Technologies) techNames.push(t.Name);
  }
} catch (e) {}

const brief = {
  domain: row.Domain,
  company: {
    name: org.name,
    industry: org.industry,
    employees: org.estimated_num_employees,
    founded: org.founded_year,
    revenue: org.annual_revenue_printed,
    total_funding: org.total_funding_printed,
    latest_funding_stage: org.latest_funding_stage,
    latest_funding_date: (org.latest_funding_round_date || '').slice(0, 10),
    location: [org.city, org.country].filter(Boolean).join(', '),
    linkedin: org.linkedin_url,
    description: org.short_description,
  },
  technologies: [...new Set(techNames)].slice(0, 30),
  news: ((news.output && news.output.data) || []).slice(0, 5).map((n) => ({
    date: (n.attributes.found_at || '').slice(0, 10),
    category: n.attributes.category,
    headline: n.attributes.headline,
  })),
  funding_rounds: ((funding.output && funding.output.data) || []).slice(0, 3).map((f) => ({
    date: f.attributes.effective_date,
    amount: f.attributes.amount,
    type: f.attributes.financing_type,
  })),
  providers: [...new Set([enrich, tech, news, funding].map((r) => r.provider).filter(Boolean))],
};

return [{ json: { domain: row.Domain, row_number: row.row_number, icp: row.icp, brief } }];

parameters.text:
=You score B2B accounts for a sales team. Use only the research below; do not invent facts.

Ideal customer profile:
{{ $json.icp }}

Account research (JSON):
{{ JSON.stringify($json.brief) }}

Give a score from 1 (poor fit) to 10 (perfect fit), a one-sentence reason, the strongest buying signal from the news or funding data (or "none"), and 2 to 4 job titles a rep should contact. Use short, common titles exactly as people write them on LinkedIn (for example CTO, VP Engineering, Head of Engineering, Engineering Manager), comma-separated.

