// Up to two people from the People Data Labs result, each carrying the account fields.
const account = $('Attach the score').first().json;
const people = ($input.first().json.output && $input.first().json.output.data) || [];
// Rank by overlap with the target titles so a seniority-only fallback still prefers the right function.
const wanted = String(account.target_titles || '').toLowerCase().split(/[,\s]+/).filter((w) => w.length > 2);
const relevance = (p) => wanted.filter((w) => String(p.job_title || '').toLowerCase().includes(w)).length;
const picked = people
  .filter((p) => p.full_name)
  .sort((a, b) => relevance(b) - relevance(a))
  .slice(0, 2)
  .map((p) => ({
    json: {
      domain: account.domain,
      full_name: p.full_name.replace(/\b\w/g, (c) => c.toUpperCase()),
      job_title: p.job_title,
      linkedin_url: p.linkedin_url ? 'https://' + p.linkedin_url.replace(/^https?:\/\//, '') : '',
      email_from_search: p.work_email || '',
    },
  }));
// No people found: still emit one item so the account is saved and routed.
return picked.length ? picked : [{ json: { domain: account.domain, full_name: '', job_title: '', linkedin_url: '', email_from_search: '' } }];

