// One row for the sheet: the score, the contacts and the opener in plain text.
const account = $('Attach the score').first().json;
const contacts = ($('Collect the contacts').first().json.data || []).filter((c) => c.full_name);
const opener = ($input.first().json.text || '').trim();
const b = account.brief;
return [{ json: {
  domain: account.domain,
  score: account.score,
  reason: account.reason,
  buying_signal: account.buying_signal,
  contacts,
  contacts_text: contacts.map((c) => `${c.full_name} (${c.job_title}) ${c.email || 'no email'}${c.email_status ? ' [' + c.email_status + ']' : ''}`).join('\n'),
  opener,
  company: b.company.name || '',
  industry: b.company.industry || '',
  employees: b.company.employees || '',
  providers: (b.providers || []).join(', '),
  top_contact: contacts[0] || null,
} }];

